/**
 * /proc/<pid>/stat 的字段下标（相对于 comm 的右括号之后的部分）。
 * man 5 proc：第一个字段是 pid、第二个是 (comm)，comm 可能含空格，
 * 所以解析从最后一个 ')' 之后开始，下标随之前移。
 *
 * utime/stime 是自身用户态/内核态 CPU 时间；
 * cutime/cstime 只累计**已被 wait 回收**的子进程时间——活着的子进程不在其中，
 * 这就是"父进程看起来不消耗资源"的根源，所以需要按进程树聚合。
 */
let _stat_index = [
  ['state', 0],
  ['ppid', 1],
  ['pgrp', 2],
  ['session', 3],
  ['utime', 11],
  ['stime', 12],
  ['cutime', 13],
  ['cstime', 14],
  ['vsize', 20],
  ['rss', 21]
]

/**
 * 进程目录中存在comm，保存命令的名称，cmdline保存完整命令格式
 * man 5 proc 参看stat部分
 * pid
 * comm 此部分表示命令名称，命令有可能会有空格，会使用()包含
 * 解析过程不能简单的使用空格分割
 */
/**
 * @param {number|string} pid
 * @param {boolean} light 轻量模式：只读 stat 一个文件（comm 从 stat 行内取），
 *   不再读 comm 与 cmdline。全量扫描进程树时用它，把每进程 3 次文件读降为 1 次。
 */
function parse_linux_stat(pid, light = false) {
  try {
    let stat = fs.readFileSync(`/proc/${pid}/stat`, {encoding: 'utf8'})

    let lastParen = stat.lastIndexOf(')')
    if (lastParen === -1) return false

     // 跳过 ') ' 最后的 )之后肯定是状态
    let infoPart = stat.substring(lastParen + 2).trim()
    let stlines = infoPart.split(' ')

    let p = {}
    let val

    p.pid = parseInt(stat.substring(0, stat.indexOf(' ')))

    for (let sti of _stat_index) {
      val = stlines[sti[1]]
      if (name_preg.test(val)) {
        p[sti[0]] = parseInt(val)
      } else {
        p[sti[0]] = val
      }
    }

    // 自身占用的 CPU 时间（不含活着的子进程，聚合由调用方按进程树完成）
    p.cputime = p.utime + p.stime

    if (light) {
      // stat 的第一对括号里就是 comm，省掉一次文件读
      let lp = stat.indexOf('(')
      p.comm = p.name = (lp >= 0 && lastParen > lp) ? stat.substring(lp + 1, lastParen) : ''
      return p
    }

    let comm = fs.readFileSync(`/proc/${pid}/comm`, {encoding: 'utf8'})
    p.comm = p.name = comm.trim()
    p.cmdline = fs.readFileSync(`/proc/${pid}/cmdline`, {encoding: 'utf8'})
    p.cmdsplit = p.cmdline.split('\x00').map(p => p.trim()).filter(p => p.length > 0)
    return p
  } catch (err) {
    return false
  }

  return false
}

function parse_ids(idtext, type = 'uid') {
  let ids = idtext.split(/\s+/).filter(p => p.length > 0)
  
  return [
    parseInt(ids[0]),
    parseInt(ids[1])
  ]
}

/**
 * 类Unix系列（主要是FreeBSD、OpenBSD等）没有/proc，似乎可以通过mount linprocfs /proc 进行兼容linux的挂载。
 * /proc/PID/status就是为了方便程序解析而提供的。
 */
async function async_parse_linux_status(pid, obj=null) {
  try {
    let stdata = await fsp.readFile(`/proc/${pid}/status`, {encoding: 'utf8'})
    let stlines = stdata.split('\n').map(d => {
      let rd = d.trim()
      let key_ind = d.indexOf(':')
      let key = d.substring(0, key_ind).toLowerCase()
      let val = d.substring(key_ind+1).trim()
      return [key, val]
    })

    let p = obj || {}
    
    let uids, gids

    stlines.forEach(st => {
      switch (st[0]) {
        case 'name':
          p.comm = st[1]
          p.name = st[1]
          break
        
        case 'vmrss':
          p.rss = parseInt(st[1])
          break

        case 'vmpte':
          p.pte = parseInt(st[1])
          break

        case 'pid':
        case 'ppid':
          p[st[0]] = parseInt(st[1])
          break

        case 'state':
          p[st[0]] = st[1]
          break

        case 'nssid':
          p.session = parseInt(st[1])
          break

        case 'nspgid':
          p.pgrp = parseInt(st[1])
          break

        case 'uid':
          uids = parse_ids(st[1])
          p.uid = uids[0]
          p.euid = uids[1]
          break

        case 'gid':
          gids = parse_ids(st[1])
          p.gid = gids[0]
          p.egid = gids[1]
          break
      }
    })

    let cmdline = await fsp.readFile(`/proc/${pid}/cmdline`, {encoding: 'utf8'})
    p.cmdline = cmdline
    p.cmdsplit = cmdline.split('\x00').map(p => p.trim()).filter(p => p.length > 0)
    return p
  } catch (err) {
    return false
  }

  return false
}

function parse_linux_status(pid) {
  try {
    let stdata = fs.readFileSync(`/proc/${pid}/status`, {encoding: 'utf8'})

    let stlines = stdata.split('\n').map(d => {
      let rd = d.trim()
      let key_ind = d.indexOf(':')
      let key = d.substring(0, key_ind).toLowerCase()
      let val = d.substring(key_ind+1).trim()
      return [key, val]
    })

    let p = {}

    let uids, gids

    stlines.forEach(st => {
      switch (st[0]) {
        case 'name':
          p.comm = st[1]
          p.name = st[1]
          break
        
        case 'vmrss':
          p.rss = parseInt(st[1])
          break

        case 'pid':
        case 'ppid':
          p[st[0]] = parseInt(st[1])
          break

        case 'state':
          p[st[0]] = st[1]
          break

        case 'nssid':
          p.session = parseInt(st[1])
          break

        case 'nspgid':
          p.pgrp = parseInt(st[1])
          break

        case 'uid':
          uids = parse_ids(st[1])
          p.uid = uids[0]
          p.euid = uids[1]
          break

        case 'gid':
          gids = parse_ids(st[1])
          p.gid = gids[0]
          p.egid = gids[1]
          break
      }
    })

    let cmdline = fs.readFileSync(`/proc/${pid}/cmdline`, {encoding: 'utf8'})
    p.cmdline = cmdline
    p.cmdsplit = cmdline.split('\x00').map(p => p.trim()).filter(p => p.length > 0)

    return p
  } catch (err) {
    return false
  }

  return false
}

/**
 *
 * 提供一个类似于ps命令的功能，输出结构提供进程列表，查询等功能。
 * 最主要的一个功能是直接提供进程树结构，并可以查找一个进程下所有子进程。
 *
 * */
function getAllChilds(pid, just_pid=false) {
    let childs = []
    let chs = []
    let pids = this.ptable[pid] || []

    /**
     * 进程表是逐个读 /proc 拼出来的，**不是原子快照**：扫描期间发生 PID 复用
     * 或重定父，理论上可以拼出 A.ppid=B、B.ppid=A 这样的环。没有 visited
     * 的话这里会无限循环（调用方包括 killAllChilds 与负载聚合），必须去重。
     */
    let seen = new Set([parseInt(pid)])

    while (true) {
      chs = []
      if (pids.length === 0) break

      for (let a of pids) {
        if (seen.has(a.pid)) continue
        seen.add(a.pid)

        childs.push(just_pid ? a.pid : a)

        if (this.ptable[a.pid]) {
          chs.push(...this.ptable[a.pid])
        }
      }
      pids = chs
    }

    return childs
}

function isChild(ppid, pid) {
  if (!this.table[pid] || !this.table[ppid]) return false

  let p = this.table[pid]
  while (p && this.table[p.ppid]) {
    if (p.ppid === ppid) {
      return this.table[p.ppid] || true
    }

    p = this.table[p.ppid]
  }

  return false
}

function getChildsByCMDLine(cmdline) {
  let csplit = cmdline.split('\x00')

  let args = csplit.slice(1).sort((a, b) => {
    return a > b ? 1 : -1
  })

  let cline = csplit[0] + ' ' + args.join(' ')
  let cmds = []

  for (let k in this.table) {
    let p = this.table[k]
    let args = p.cmdsplit.slice(1).sort((a,b) => {
      return a > b ? 1 : -1
    })

    let p_cmdline = `${p.cmdsplit[0]} ${args.join(' ')}`

    if (p_cmdline === cline) {
      cmds.push(p)
    }
  }

  return cmds
}

/**
 * 根据名称和参数查找
 * @param {object} nametable
 * @param {array} args
 * */
function getChildsByCMDArgs(nametable, args) {
  let argstable = {}
  let count = args.length

  args.forEach(x => {
    argstable[x] = true
  })

  let cmds = []

  for (let k in this.table) {
    let p = this.table[k]
    if (!nametable[p.cmdsplit[0]]) continue

    let args = p.cmdsplit.slice(1)
    let ac = 0
    args.forEach(x => {
      argstable[x] && (ac++)
    })
    
    ;(count <= 0 || ac >= count) && cmds.push(p)
  }

  return cmds
}

function getChildsByCOMM(name) {
  let cmds = []
  for (let k in this.table) {
    let p = this.table[k]
    if (p.comm === name) {
      cmds.push(p)
    }
  }
  return cmds
}

/**
 * 自底向上聚合：给树上每个节点算出"自身 + 全部后代"的合计。
 *
 * 规则（重要）：**节点自身的属性永远只表示自己的占用**，
 * 合计写到独立的属性上（默认 <key>Total），互不覆盖。
 * 这样 A 的合计 = A 自身 + 各直接子节点的合计，天然是递归关系；
 * 每一层都能单独回答"这一层往下总共占了多少"。
 *
 * @param {string[]} keys 要聚合的数值属性名，如 ['cputime', 'rss']
 * @param {string} suffix 合计属性的后缀，默认 'Total'
 * @returns {object} this（便于链式调用）
 */
function sumTree(keys = ['cputime', 'rss'], suffix = 'Total') {
  let self = this

  // 显式栈的后序遍历：进程树深度理论上可以很深，避免递归爆栈
  let roots = []

  for (let pid in self.table) {
    let p = self.table[pid]
    if (!self.table[p.ppid]) roots.push(p)
  }

  /**
   * 按深度分层收集，再从最深层往上累加（等价于后序遍历，但不用递归，避免深树爆栈）。
   * seen 不只是优化：进程表非原子快照，可能拼出环，没有它这个循环不会结束。
   */
  let layers = []
  let cur = roots
  let seen = new Set(roots.map(r => r.pid))

  while (cur.length > 0) {
    layers.push(cur)
    let next = []

    for (let n of cur) {
      let cs = self.ptable[n.pid] || []
      for (let c of cs) {
        if (seen.has(c.pid)) continue
        seen.add(c.pid)
        next.push(c)
      }
    }

    cur = next
  }

  for (let i = layers.length - 1; i >= 0; i--) {
    for (let node of layers[i]) {
      let childs = self.ptable[node.pid] || []

      for (let k of keys) {
        node[k + suffix] = typeof node[k] === 'number' ? node[k] : 0
      }

      node.procTotal = 0

      for (let c of childs) {
        // 只累加本轮实际访问过的子节点，避免环内节点被重复计入
        if (!seen.has(c.pid) || c[keys[0] + suffix] === undefined) continue

        for (let k of keys) {
          node[k + suffix] += c[k + suffix] || 0
        }

        node.procTotal += 1 + (c.procTotal || 0)
      }
    }
  }

  /**
   * 兜底：环内节点不属于任何根的子树，上面的遍历访问不到，
   * 合计属性会是 undefined，后续参与算术就变成 NaN。
   * 这类节点按"只有自己"处理。
   */
  for (let pid in self.table) {
    let node = self.table[pid]

    if (node[keys[0] + suffix] !== undefined) continue

    for (let k of keys) {
      node[k + suffix] = typeof node[k] === 'number' ? node[k] : 0
    }

    node.procTotal = 0
  }

  return self
}

function initProcessTreeData() {
  return {
      table: {},
      ptable: {},
      getAllChilds: getAllChilds,
      //检测pid是否为ppid的子进程
      isChild: isChild,
      getChildsByCMDLine: getChildsByCMDLine,
      getChildsByCOMM: getChildsByCOMM,
      getChildsByCMDArgs: getChildsByCMDArgs,
      //自底向上聚合出"含后代"的合计属性
      sumTree: sumTree
  }
}

/**
 * 基于 /proc/<pid>/stat 的进程树：与 nps() 结构一致，但每个节点带
 * CPU 时间（cputime/utime/stime）与内存（rss 页数、vsize），
 * 且每进程只读一个文件（nps() 读 status + cmdline 两个）。
 *
 * @param {boolean} aggregate 是否顺带聚合出 cputimeTotal / rssTotal / procTotal
 */
function npstat(aggregate = true) {
  let processData = initProcessTreeData()
  if (process.platform !== 'linux') return processData

  let rlist = getProcList()
  let p

  for (let pid of rlist) {
    p = parse_linux_stat(pid, true)
    if (!p) continue

    processData.table[p.pid] = p

    if (!processData.ptable[p.ppid]) {
      processData.ptable[p.ppid] = []
    }

    processData.ptable[p.ppid].push(p)
  }

  if (aggregate) processData.sumTree(['cputime', 'rss'])

  return processData
}

function nps() {
  let processData = initProcessTreeData()
  if (process.platform !== 'linux') return processData

  let rlist = getProcList()

  let p, cur

  for (let pid of rlist) {
    p = parse_linux_status(pid)
    if (!p) continue

    processData.table[pid] = p
    if (!processData.ptable[p.ppid]) {
      processData.ptable[p.ppid] = []
    }

    processData.ptable[p.ppid].push(p)
  }
  
  return processData
}

async function anps() {
  let processData = initProcessTreeData()
  if (process.platform !== 'linux') return processData

  let rlist = getProcList()

  let p, cur

  for (let pid of rlist) {
    p = await async_parse_linux_status(pid)
    if (!p) continue

    processData.table[pid] = p
    if (!processData.ptable[p.ppid]) {
      processData.ptable[p.ppid] = []
    }

    processData.ptable[p.ppid].push(p)
  }
  
  return processData
}

module.exports = {
  nps,
  anps,
  npstat,
  parse_linux_stat,
  parse_linux_status,
  async_parse_linux_status
}
